// Boundary check of MAX_IMPORT_BYTES using the real app/backup.js. Not a committed test.
const path = require('path');
const backup = require(path.resolve(process.argv[2], 'app/backup.js'));
const { MAX_IMPORT_BYTES, MESSAGES, toBackupText, tooBigToImport, importBackup } = backup;

const bytes = (s) => Buffer.byteLength(s, 'utf8');

// A valid backup whose UTF-8 size is exactly `target` bytes. `filler` is the repeated title char ('a' = 1 byte, 'ệ' = 3 bytes).
function backupOfSize(target, filler) {
  const make = (head, pad) => toBackupText([{ id: 'x1', title: head + 'a'.repeat(pad), done: false, createdAt: 1 }]);
  const base = bytes(make('', 0));
  const fb = bytes(filler);
  const n = Math.floor((target - base) / fb);
  const text = make(filler.repeat(n), target - base - n * fb);
  if (bytes(text) !== target) throw new Error(`built ${bytes(text)} bytes, wanted ${target}`);
  return text;
}

const store = () => ({ readError: false, replace: () => 'saved' });
const label = (m) => (m === MESSAGES.fileTooBig ? 'fileTooBig' : m && m.startsWith('Đã nhập') ? `imported ("${m}")` : JSON.stringify(m));

(async () => {
  console.log('MAX_IMPORT_BYTES =', MAX_IMPORT_BYTES);
  for (const filler of ['a', 'ệ']) {
    for (const size of [MAX_IMPORT_BYTES - 1, MAX_IMPORT_BYTES, MAX_IMPORT_BYTES + 1]) {
      const text = backupOfSize(size, filler);
      const file = new Blob([text]);
      const res = await importBackup({ store: store(), current: [], file, ask: async () => true });
      console.log(
        `filler=${filler} bytes=${bytes(text)} chars=${text.length} blob.size=${file.size}` +
          ` tooBigToImport=${tooBigToImport(text)} importBackup=${label(res.message)}`,
      );
    }
  }
})();

